-- 98a_grade77_data.sql — ข้อมูลผลการเรียน ผู้สำเร็จการศึกษา รุ่น 77 (ปีการศึกษา 2565–2568)
-- ----------------------------------------------------------------------------
-- ที่มา: ไฟล์ "ผลการเรียน ชั้นปีที่ 4 รุ่น 77 2565-2568.xlsx" (4 แผ่นงาน)
--   • เฉพาะผู้สำเร็จการศึกษา 166 คน (รายชื่อในแผ่นปี 4) — ผู้ที่ลาออก/พักการเรียนไม่อยู่ในชุดนี้
--   • 7802 รายการเกรด · 48 รายวิชา · ทุกคนครบ 124 หน่วยกิต
--   • ตรวจแล้ว: GPA รายภาคที่คำนวณจากข้อมูลชุดนี้ตรงกับไฟล์ทุกภาค ทุกคน
-- ไฟล์นี้ "ยังไม่แตะ" ตารางของระบบ — เก็บข้อมูลไว้ในตารางพัก ems._g77_* เท่านั้น
-- ลำดับ: 98a (ไฟล์นี้) → 98b ตรวจ → 98c บันทึกจริง
-- วิธีใช้: Supabase → SQL Editor → วางทั้งไฟล์ → Run (รันซ้ำได้)
-- ============================================================================
drop table if exists ems._g77_grade, ems._g77_course, ems._g77_student;
create table ems._g77_course (code text primary key, name_th text, credits numeric, credit_code text);
create table ems._g77_student (student_id text primary key, name text, gpax_file numeric, gpax_calc numeric, honors_file text, honors_blocked boolean, honors text);
create table ems._g77_grade (student_id text, code text, grade text, semester text, academic_year text);

